PREFIX brick: <http://brickschema.org/brick#>
PREFIX ref: <http://brickns.github.io/brick#ref>
SELECT ?label ?tsid WHERE {
  ?z rdfs:label "Perimeter_top_ZN_2" .
  ?point ref:hasTimeseriesId ?tsid .
  { ?point brick:isPartOf ?z } UNION { ?point brick:hasPoint ?z } UNION { ?z brick:hasPoint ?point } UNION { ?z brick:isPartOf ?point }
}

SELECT DISTINCT ?label WHERE {
  ?z rdfs:label ?label ; a brick:Zone .
}

