  ?point brick:isPointOf ?z .
  ?z rdfs:label "Perimeter_top_ZN_2" .
  OPTIONAL { ?point a ?cls }
}

SELECT ?z ?label WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?label .
} LIMIT 50

SELECT ?point ?ext WHERE {
  ?z rdfs:label "Perimeter_top_ZN_2" .
  ?point brick:isPointOf ?z .
  ?point ref:hasExternalReference ?ext .
  FILTER(?point brick:isPointOf ?z)
}

SELECT ?point ?ext ?cls WHERE {
  ?z rdfs:label "Perimeter_top_ZN_2" .
  ?point brick:isPointOf ?z .
  FILTER(?point brick:isPointOf ?z)
  ?point a ?cls .
  OPTIONAL { ?point ref:hasExternalReference ?ext }
}

SELECT ?point ?ext ?cls WHERE {
  ?z rdfs:label "Perimeter_top_ZN_2" .
  ?point brick:isPointOf ?z .
  ?point a ?cls .
  OPTIONAL { ?point ref:hasExternalReference ?ext }
}

